package com.wizzadrds.theworldremembers; import com.wizzadrds.theworldremembers.knowledge.*; import net.fabricmc.fabric.api.gametest.v1.GameTest; import net.minecraft.gametest.framework.GameTestHelper; import net.minecraft.world.entity.EntityTypes; public final class ConversationPropagationGameTest{@GameTest public void conversationTransfersKnownEvent(GameTestHelper c){var a=c.spawn(EntityTypes.VILLAGER,2,1,2);var b=c.spawn(EntityTypes.VILLAGER,4,1,2);var subject=c.spawn(EntityTypes.VILLAGER,3,1,4);c.runAtTickTime(1,()->{var k=KnowledgeManager.get(c.getLevel().getServer());k.addDirect(a.getUUID(),"event-1","npc_died",subject.getUUID(),1);var cm=ConversationManager.get(c.getLevel().getServer());if(!cm.talk(a.getUUID(),b.getUUID(),"event-1",2)){c.fail("Conversation did not transfer knowledge");return;}var facts=k.factsOf(b.getUUID());if(facts.stream().noneMatch(f->f.eventId().equals("event-1")&&f.origin()==KnowledgeOrigin.REPORTED)){c.fail("Listener did not receive reported knowledge");return;}c.succeed();});}}